                            <>
                              <button
                                onClick={() => handleApproveFromModal(idx)}
                                disabled={actioningMilestoneId !== null}
                                style={{
                                  padding: '0 8px',
                                  height: '30px',
                                  background: '#10b981',
                                  color: 'white',
                                  border: 'none',
                                  borderRadius: '6px',
                                  display: 'inline-flex',
                                  alignItems: 'center',
                                  justifyContent: 'center',
                                  cursor: actioningMilestoneId !== null ? 'not-allowed' : 'pointer',
                                  fontSize: '0.7rem',
                                  fontWeight: 700,
                                  opacity: actioningMilestoneId !== null ? 0.6 : 1
