                  fontWeight: 700,
                  color: activeDrawerTab === 'history' ? 'var(--color-primary)' : 'var(--color-text-muted)',
                  borderBottom: activeDrawerTab === 'history' ? '2px solid var(--color-primary)' : '2px solid transparent',
